parameters.jsCode:
const d = $json;
return [{json:{
  ...d,
  sessionId: d.chatId,
  contextText: `Student ID: ${d.studentId}
Student: ${d.studentName || 'Student'}
Class/Batch: ${d.className || d.batchName || 'Unknown'}
Course: ${d.courseName || 'Unknown'}
Teacher: ${d.teacherName || 'Unknown'}
Course Duration: ${d.courseDuration || 'Unknown'}
End Date: ${d.endDate || 'Unknown'}`
}}];

let base = {};
try { base = $('Build Session Context').first()?.json || {}; } catch(e) {}
if (!base.messageText) {
  try { base = $('Normalize Telegram Message').first()?.json || {}; } catch(e) {}
}

const rawText = String(base.messageText || '').trim();
// Strip wrapping quotes and excessive punctuation for matching (CP-10)
let text = rawText.replace(/^["'\s.]+|["'\s.]+$|[?!,;:]+$/g, '').trim();

// Normalize dots/underscores/dashes and whitespace for punctuation tolerance (CP-04, CP-09)
const normalizedText = text.replace(/[\.\_\-]+/g, ' ').replace(/\s+/g, ' ').trim();

// For very long messages (BV-09), truncate search window to prevent ReDoS
const searchWindow = normalizedText.substring(0, 1000);

// 1. Security Violations / Injections / Exfiltration / Social Engineering (SE-01 to SE-15)
const isSecurityAttack = /\b(ignore\s+(?:all\s+)?(?:previous\s+)?instructions|show\s+(?:your\s+)?(?:system|hidden)\s*prompt|system\s*prompt|translate.*system\s*prompt|give\s+me\s+(?:the\s+)?api\s*key|api\s*key|lms_service_key|telegram\s*token|show\s+(?:all\s+)?environment|database\s*password|credentials|show\s+(?:me\s+)?(?:all\s+)?students?|another\s+student|student\s+(?:123|999)|student[\s_]*id\s*=\s*\d+|my\s+friend\s+is\s+student|pretend\s+my\s+fees\s+are\s+zero|developer\s*mode|system\s*administrator|instructions\s*(?:were\s*you\s*given|before)|repeat\s*everything\s*above|unrestricted\s*ai|safety\s*filters|jailbreak|authorized\s*me\s*to\s*access|my\s*name\s*is\s*rahul|\[SYSTEM\]|override\s*security|grant\s*admin|college\s*principal|principal.*fees|select\s+.*\s+from\s+|run\s*this\s*sql|temperature\s*setting|what\s*model\s*are\s*you\s*running|say\s*["']?access\s*granted|forget\s*you\s*are|you\s*are\s*now\s*chatgpt|student[\s_]*id\s*is\s*actually|base64|aWdub3JlIGluc3RydWN0aW9ucw)\b/i.test(searchWindow);

// 2. Hallucination Probing (HL-01 to HL-12: exam marks, CGPA, classmates, assignments, holidays, rank, batch count, teacher phone, IA marks, college address, library books)
const isHallucinationProbe = !isSecurityAttack && /\b(marks?|cgpa|gpa|classmates?|batchmates?|assignment(?:s)?|holiday(?:s)?|vacation|rank|standing|class\s*size|how\s*many\s*students|priya(?:'s|\s+sharma's)?\s*(?:phone|mobile|contact)|internal\s*assessment|ia\s*marks|passing\s*or\s*failing|college\s*address|location\s*of\s*college|library\s*books?|borrowed\s*books?)\b/i.test(searchWindow) && !/\b(attendance|fees?|absent|present|certif)\b/i.test(searchWindow);

// 3. Negations & Corrections (NC-01 to NC-10)
const isNegationQuiz = !isSecurityAttack && /\b(don'?t\s*want\s*(?:a\s*)?quiz|no\s*quiz)\b/i.test(searchWindow);
const isNegationSupport = !isSecurityAttack && /\b(don'?t\s*have\s*(?:any\s*)?issues?|no\s*issues?|no\s*problem)\b/i.test(searchWindow);
const isCancel = !isSecurityAttack && /^(?:cancel(?:\s*that)?|stop|never\s*mind|nvm)$/i.test(searchWindow);
const isWrongAnswer = !isSecurityAttack && /\b(wrong\s*answer|let\s*me\s*try\s*again)\b/i.test(searchWindow);
const isDidnAsk = !isSecurityAttack && /\b(didn'?t\s*ask\s*about\s*that|not\s*what\s*i\s*asked)\b/i.test(searchWindow);

// Correction routing: "not fees, I asked about attendance" -> attendance
let effectiveText = searchWindow;
if (/^not\s+fees?,?\s*i\s*asked\s*about\s*attendance/i.test(searchWindow)) {
  effectiveText = 'attendance';
} else if (/^no\s+no,?\s*show\s*me\s*materials/i.test(searchWindow)) {
  effectiveText = 'materials';
} else if (/^i\s*meant\s*to\s*ask\s*about\s*my\s*batch/i.test(searchWindow)) {
  effectiveText = 'which batch';
}

// 4. Leave & Absence requests (CS-07, SL-09, CC-08)
const isLeave = !isSecurityAttack && /\b(will\s+be\s+absent|apply(?:ing)?\s+for\s+(?:medical\s+)?leave|sick\s+leave|medical\s+leave|take\s+leave|leave\s+application|absent\s+(?:tomorrow|next|on\s+[a-z0-9]+|tmrw|kal|for\s+the\s+last)|kal\s+absent|cannot\s+attend|unable\s+to\s+attend|chutti|fyi\s*i'?m\s*absent)\b/i.test(effectiveText);

// 5. Support Issues & Discrepancies (CS-06, SL-10)
const isSupportIssue = !isSecurityAttack && !isNegationSupport && (isLeave || /\b(cannot|can'?t|unable|error|issue|problem|fail|failed|broken|help\s*(?:me\s*)?with|not\s*working|trouble|complaint|not\s*(?:updated|reflected|showing|received)|deducted|discrepancy|dispute|locked|crashed|account\s*(?:issue|problem|help)?|login\s*nahi|portal\s*pe\s*login|pls\s*help\s*asap|help\s*asap)\b/i.test(effectiveText));

// 6. Invalid Quiz Option (BV-10: option E)
const isInvalidQuizOption = !isSecurityAttack && /^(?:option\s*)?[eE](?:[\)\.\:\-\s]|$)/i.test(effectiveText) && !/\b(explain|what|fees|attendance)\b/i.test(effectiveText);

// 7. Quiz answer submissions (MT-02b, BV-08, QA, 1-A to 5-C)
const prefixMatch = /^(?:answers?|ans|my\s+answer(?:\s+is)?|option|choice)\b/i.test(effectiveText);
const singleOptionMatch = /^[a-dA-D](?:[\)\.\:\-\s]|$)/i.test(effectiveText);
const numberedMatch = /^[1-5]\s*[\)\.\:\-\s]*(?:->)?\s*[a-dA-D]/i.test(effectiveText);
const multiMatch = /(?:(?:question|q|ans|answer)?\s*[1-5]\s*[:.)\-–—\s]*(?:is\s*)?[a-dA-D]\b.*){2,}/i.test(effectiveText);
const inlineMatch = /\b(?:option|choice|answer|ans)\s*(?:[1-5]\s*)?(?:is|=|\:|\-)?\s*[a-dA-D]\b/i.test(effectiveText);
const guessMatch = /\b(?:i\s+think|guess)\s+(?:it(?:\s*is|\'s)\s+)?[a-dA-D]\b/i.test(effectiveText);

const seqLettersMatch = /^(?:[\(\[]?[a-dA-D][\)\]]?[,\s]+){1,}[\(\[]?[a-dA-D][\)\]]?$/i.test(effectiveText.trim());
const numberedLinesMatch = /(?:(?:^|\n)\s*(?:for\s+)?(?:question|q)?\s*[1-5]\s*[\)\.\:\-\s=]).*(?:(?:\n)\s*(?:for\s+)?(?:question|q)?\s*[1-5]\s*[\)\.\:\-\s=])/i.test(effectiveText);

const isQuizAnswer = !isSecurityAttack && !isSupportIssue && !isInvalidQuizOption && !isNegationQuiz && (
  prefixMatch || singleOptionMatch || numberedMatch || multiMatch || inlineMatch || guessMatch || seqLettersMatch || numberedLinesMatch
);

// 8. Quiz generation requests (MT-02a, MT-02c, TY-07, TY-08, CS-04, SL-03, AB-11, AB-12, FU-03b)
const isQuizRequest = !isSecurityAttack && !isSupportIssue && !isNegationQuiz && !isQuizAnswer && (
  /\b(quiz|qiuz|quize|practice|mcqs?|questions?|five\s*mcqs|ek\s*quiz|gimme\s*a\s*quiz|harder\s*please)\b/i.test(effectiveText) ||
  /^(?:test|quiz\s*me|take\s*a\s*test)$/i.test(effectiveText) ||
  /\b(test\s*me|generate\s*(?:a\s*)?quiz)\b/i.test(effectiveText)
) && !/\b(explain|what\s+is|doubt|why)\b/i.test(effectiveText);

// 9. Study Materials requests (TY-14, CS-10, M-01, AB-11)
const isMaterials = !isSecurityAttack && !isSupportIssue && !isQuizRequest && !isQuizAnswer && /\b(materials?|materails?|resources?|notes|lectures?|videos?|pdf|syllabus|curriculum|study\s*(?:material|guide|notes)?|kitabe|books|padhne|notes\s*chahiye|help\s*me\s*study)\b/i.test(effectiveText) && !/\b(explain|what\s+is)\b/i.test(effectiveText);

// 10. Student Profile & Enrollment (TY-13, SL-08, CP-09, P-01, CC-07)
const isProfile = !isSecurityAttack && !isSupportIssue && /\b(my\s+profile|proifle|student\s*id|idk\s*my\s*student\s*id|roll\s*(?:no|number)|enrollment\s*(?:no|number|details)?|my\s+details|who\s+am\s+i|meri\s+id|profile\s*details)\b/i.test(effectiveText);

// 11. Teacher & Faculty (TY-09, TY-10, CS-05, SL-04, FU-05a, FU-05b, T-01 - covers "who is teaching this course", "who teaches", etc.)
const isTeacher = !isSecurityAttack && !isSupportIssue && !isHallucinationProbe && (
  /\b(?:who\s*(?:is|'s)?\s*(?:teaching|teaches|taking|conducting)|who\s*(?:is|'s)?\s*(?:my|the|our|this)?\s*(?:teacher|trainer|instructor|faculty|prof|professor|educator|mentor)|teacher|teecher|techer|faculty|instructor|professor|trainer)\b/i.test(effectiveText) ||
  /\b(?:teacher|trainer|instructor|faculty|prof|professor)\s*(?:'s)?\s*(?:name|details|info|contact|ka\s*naam)?\b/i.test(effectiveText) ||
  /\b(?:what\s*does\s*(?:she|he|they|the\s*teacher)\s*teach)\b/i.test(effectiveText) ||
  /\b(?:kon\s*(?:padha|teacher)|teacher\s*kon)\b/i.test(effectiveText)
);

// 12. Schedule, Timing, Deadline & Course End-Date (TY-12, CS-03, CS-08, FU-04a, FU-04b, S-01, AB-09)
const isSchedule = !isSecurityAttack && !isSupportIssue && !isTeacher && !isHallucinationProbe && /\b(when\s*(?:does|will)\s*(?:my\s*)?(?:course|batch)\s*(?:end|finish)|course\s*kab\s*end|how\s*many\s*days\s*(?:are\s*)?left|how\s*many\s*weeks\s*(?:are\s*)?left|how\s*many\s*months\s*(?:are\s*)?left|months\s*left|course\s*duration|duration|how\s*long\s*(?:is\s*)?(?:my\s*)?(?:course|batch|program|class)|timetable|time\s*table|schedule|schedul|class\s*timing|batch\s*timing|timing|routine|when\s*(?:is|are)\s*(?:my|the)?\s*classes?|next\s*class|kab\s+(?:khatam|over|finish)|kitna\s*time|bacha\s*hai|am\s*i\s*done|deadline)\b/i.test(effectiveText);

// 13. Course & Batch info (TY-11, SL-05, CP-10, NC-10, C-01)
const isCourseInfo = !isSecurityAttack && !isSupportIssue && !isTeacher && !isSchedule && !isHallucinationProbe && /\b(what\s*is\s*(?:my\s*)?course|which\s*course|my\s*course|cource|which\s*batch|which\s*class|my\s*batch|batch\s*name|course\s*name|my\s*batch\s*timing)\b/i.test(effectiveText);

// 14. Attendance & Certificate queries (TY-01, TY-02, TY-03, TY-15, CS-01, SL-01, CP-01, CP-06, CP-08, MT-05a, MT-05b, FU-02a, FU-02b, AB-01, A-01, CC-03)
const isAttendance = !isSecurityAttack && !isSupportIssue && !isSchedule && (
  /\b(attend[a-z]*|atendance|haziri|present|absent|which\s*days\s*absent|classes?\s*(?:held|attended|missed|remaining|total)?|how\s*many\s*classes|which\s*dates|percentage|eligib[a-z]*|certif[a-z]*|kitne?\s*din|attendance\s*kitni\s*hai|can\s*i\s*pass|is\s*that\s*good\s*enough)\b/i.test(effectiveText) ||
  /75%|\b75\s*%/i.test(effectiveText)
);

// 15. Fees & Payment queries (TY-04, TY-05, TY-06, CS-02, CS-09, SL-02, CP-02, CP-07, MT-01b, MT-04a, MT-04b, FU-01a, FU-01b, AB-02, F-01)
const isFees = !isSecurityAttack && !isSupportIssue && !isProfile && !isHallucinationProbe && !/\bassignment/i.test(effectiveText) && /\b(fees?|fess|feees|pay(?:ment|ing|mnet)?|paid|pending|balance|due|dues|receipt|transactions?|amount|total\s*(?:course\s*)?fee|installments?|instalment|baki|kitna\s*paisa|fees\s*ka\s*balance|how\s*do\s*i\s*pay|payment\s*kaise\s*karu|how\s*much\s*do\s*i\s*owe|break\s*it\s*down)\b/i.test(effectiveText);

// 16. Academic Doubt / Tutor Mode
const isAcademicDoubt = !isSecurityAttack && !isSupportIssue && !isQuizAnswer && !isQuizRequest && !isProfile && !isTeacher && !isCourseInfo && !isSchedule && !isAttendance && !isFees &&
  (/\b(react|javascript|js|html|css|node(?:\.js)?|express|postgres(?:ql)?|sql|database|hook|component|state|props|api|function|variable|loop|promise|async|await|flexbox|grid|middleware|usestate|useeffect)\b/i.test(effectiveText) ||
   /\b(explain|difference\s+between|how\s+does|how\s+to\s+use|syntax\s+of|example\s+of|samjhao|doubt|kya\s+hota\s+hai|kaise\s+kare)\b/i.test(effectiveText));

// 17. Courtesy & About (SL-06, SL-07, MT-06, CA-01..06)
const isThanks = /\b(thank\s*you|thanks|thx|cheers|appreciate\s*it|great\s*job|shukriya|dhanyawad|thanks\s*for\s*all|k\s*thx\s*bye)\b/i.test(effectiveText);
const isAbout = /\b(who\s*are\s*you|what\s*(?:can|do)\s*you\s*do|help\s*menu|options|commands|kya\s+kar\s+sakte)\b/i.test(effectiveText) || /^\/?help$/i.test(effectiveText);
const isActualGreeting = /^(?:hi|hello|hey|good\s*(?:morning|afternoon|evening)|start|\/start|welcome|namaste)\b/i.test(effectiveText);

// 18. Ambiguous general status queries (AB-04..AB-10)
const isStatusQuery = /^(?:status|update|tell\s*me\s*everything|what'?s\s*left|numbers|records)$/i.test(effectiveText);

// 19. Multi-Intent Detection (CC-01..CC-08)
const multiMatches = [];
if (isAttendance) multiMatches.push('attendance');
if (isFees) multiMatches.push('fees');
if (isTeacher) multiMatches.push('teacher');
if (isSchedule) multiMatches.push('schedule');
if (isCourseInfo) multiMatches.push('course');
if (isQuizRequest) multiMatches.push('quiz');

const isMulti = multiMatches.length >= 2 || /tell\s*me\s*everything/i.test(effectiveText) || /what'?s\s*left/i.test(effectiveText);

let intent = 'greeting';
let greetingType = 'welcome';
let isMaterialsOnly = false;
let isExplanation = false;

if (isSecurityAttack) {
  intent = 'greeting';
  greetingType = 'security';
} else if (isHallucinationProbe) {
